            newsCategory = "Child-friendly"
        } else if age >= 18 && age < 25 {
            newsCategory = "Young adult"
        } else if age >= 25 && age < 40 {
            newsCategory = "Adult"
        } else if age >= 40 {
            newsCategory = "Senior"
        }

        // Get news for selected category
        let news = getNewsForCategory(newsCategory: newsCategory)

        return news
